def refund(face, remain, to_cash=False):
    if to_cash:
        return remain
    rate = 95 if face > 50000 else 90
    return remain * rate // 100
for face, remain in [(50000, 20000), (100000, 20000)]:
    print(face, remain, refund(face, remain), refund(face, remain, True))
# 50000 20000 18000 20000
# 100000 20000 19000 20000

from collections import Counter
ours = {"G001": 10000, "G002": 50000, "G003": 30000, "G004": 20000}
theirs = [("G001", 10000), ("G002", 55000), ("G004", 20000), ("G004", 20000), ("G005", 10000)]
cnt = Counter(k for k, _ in theirs)
their_amt = dict(theirs)
for k in sorted(set(ours) | set(their_amt)):
    if k not in their_amt:   print(k, "판매처 파일에 없음")
    elif k not in ours:      print(k, "우리 원장에 없음")
    elif cnt[k] > 1:         print(k, f"판매처 파일에 {cnt[k]}번")
    elif ours[k] != their_amt[k]: print(k, f"금액 다름 {ours[k]} / {their_amt[k]}")
    else:                    print(k, "일치")
# G001 일치
# G002 금액 다름 50000 / 55000
# G003 판매처 파일에 없음
# G004 판매처 파일에 2번
# G005 우리 원장에 없음
